import { Component, OnInit } from '@angular/core';
import { ProductService } from '../../../services/product.service';
import { Product } from '../../../models';
import { CartService } from '../../../services/cart.service';

@Component({
  selector: 'app-shop-home',
  standalone: false,
  template: `
    <div class="shop">
      <h1>Menu</h1>
      <div class="products-grid">
        <app-product-card *ngFor="let p of products" [product]="p" (add)="onAdd($event)"></app-product-card>
      </div>
    </div>
  `,
  styles: [`
    .products-grid { display:grid; grid-template-columns:repeat(auto-fit,minmax(220px,1fr)); gap:16px; }
  `]
})
export class ShopHomeComponent implements OnInit {
  products: Product[] = [];
  loading = true;
  constructor(private productService: ProductService, private cart: CartService) {}

  ngOnInit() {
    this.productService.list().subscribe({
      next: p => { this.products = p; this.loading = false; },
      error: () => { this.loading = false; }
    });
  }

  onAdd(item: Product) {
    this.cart.add({ productId: item.id, name: item.name, price: item.price, qty: 1, image: item.image });
  }
}
